#include <gint/display.h>
#include <gint/keyboard.h>

int main(void)
{
    dclear(C_WHITE);
    dtext(10, 10, C_BLACK, "Bonjour GRAPH 90+E !");
    dupdate();

    getkey();
    return 1;
}

while(1)
{
    dclear(C_WHITE);
    dtext(10, 10, C_BLACK, "EXIT pour quitter");
    dupdate();

    key_event_t ev = getkey();
    if(ev.key == KEY_EXIT)
        break;
}

int running = 1;
while(running)
{
    while(pollevent().type != KEYEV_NONE) {}

    if(keydown(KEY_LEFT))  x -= 2;
    if(keydown(KEY_RIGHT)) x += 2;
    if(keydown(KEY_UP))    y -= 2;
    if(keydown(KEY_DOWN))  y += 2;
    if(keydown(KEY_EXIT))  running = 0;

    dclear(C_WHITE);
    drect(x, y, x + 15, y + 15, C_RED);
    dupdate();
}

dtext_opt(
    DWIDTH / 2, 20,
    C_BLACK, C_NONE,
    DTEXT_CENTER, DTEXT_TOP,
    "Titre centre", -1
);

if(x < 0) x = 0;
if(y < 0) y = 0;
if(x > DWIDTH - width)  x = DWIDTH - width;
if(y > DHEIGHT - height) y = DHEIGHT - height;

#include <gint/rtc.h>

rtc_time_t now;
rtc_get_time(&now);

dprint(10, 10, C_BLACK, "%02d:%02d:%02d",
       now.hours, now.minutes, now.seconds);

extern bopti_image_t img_sprite;

/* Dans la boucle de rendu */
dimage(x, y, &img_sprite);

key_event_t ev = getkey();
switch(ev.key)
{
    case KEY_F1: page = 0; break;
    case KEY_F2: page = 1; break;
    case KEY_F3: page = 2; break;
    case KEY_EXIT: running = 0; break;
}
